import datetime
import os
import types
from src.features.memory import cli

class FixedDateTime:
    @classmethod
    def now(cls, tz):
        return datetime.datetime.fromisoformat(os.environ["CHARLIEBOT_MEMORY_CLI_TEST_NOW"].replace("Z", "+00:00"))

cli.datetime = types.SimpleNamespace(datetime=FixedDateTime, UTC=datetime.timezone.utc)
